<?php $copy = is_array($page ?? null) ? trim((string) ($page['content'] ?? '')) : ''; ?>
<section class="section-space"><div class="page-shell grid gap-8 lg:grid-cols-[.8fr_1.2fr]"><div><p class="eyebrow"><i class="ph ph-chats" aria-hidden="true"></i><span>Support</span></p><h1 class="section-title mt-4"><?= e($page['title'] ?? 'Contact OEMS') ?></h1><p class="mt-5 text-[var(--ink-muted)]"><?= e($copy !== '' ? $copy : 'Send the team a message. We reply by email when a response is needed.') ?></p></div><form class="dashboard-panel grid gap-5" action="/contact/submit" method="post" novalidate><input type="hidden" name="_token" value="<?= e($csrfToken) ?>"><div class="sr-only" aria-hidden="true"><label for="contact-website">Website</label><input id="contact-website" name="website" tabindex="-1" autocomplete="off"></div><?php foreach ([['name','Name','text',100],['email','Email','email',190],['subject','Subject','text',180]] as [$key,$label,$type,$max]): ?><div class="field-group"><label for="contact-<?= e($key) ?>"><?= e($label) ?></label><input id="contact-<?= e($key) ?>" name="<?= e($key) ?>" type="<?= e($type) ?>" maxlength="<?= e($max) ?>" value="<?= old_value($old, $key) ?>" required aria-describedby="contact-<?= e($key) ?>-help<?= field_error($errors, $key) ? ' contact-' . e($key) . '-error' : '' ?>"<?= field_error($errors, $key) ? ' aria-invalid="true"' : '' ?>><p id="contact-<?= e($key) ?>-help" class="field-help"><?= $key === 'email' ? 'Replies are sent only to this address.' : 'Required.' ?></p><?php if ($error = field_error($errors, $key)): ?><p id="contact-<?= e($key) ?>-error" class="field-error" role="alert"><?= e($error) ?></p><?php endif; ?></div><?php endforeach; ?><div class="field-group"><label for="contact-message">Message</label><textarea id="contact-message" name="message" maxlength="4000" rows="7" required aria-describedby="contact-message-help<?= field_error($errors, 'message') ? ' contact-message-error' : '' ?>"<?= field_error($errors, 'message') ? ' aria-invalid="true"' : '' ?>><?= old_value($old, 'message') ?></textarea><p id="contact-message-help" class="field-help">10 to 4000 characters. Do not include passwords or payment secrets.</p><?php if ($error = field_error($errors, 'message')): ?><p id="contact-message-error" class="field-error" role="alert"><?= e($error) ?></p><?php endif; ?></div><button class="button button--primary" type="submit"><i class="ph ph-paper-plane-tilt" aria-hidden="true"></i><span>Send message</span></button></form></div></section>
